const OUTFIT_RULE='. 크리스탈·김나영·미우미우 같은 세련된 성인 여성의 옷. 적힌 고급 브랜드 옷을 심플하게, 핏과 비율로 잘 입어 보이게. 무채색·네이비·카멜·크림 위주로 차분하게. 유치하거나 어려 보이는 차림(니삭스·흰 삭스, 체크 미니스커트, 셔츠에 넥타이, 럭비 셔츠, 카라 달린 니트 폴로·피케 셔츠, 레그워머, 그래픽·밴드 티, 크롭 스웨트셔츠, 원색, 귀여운 캐릭터 소품), 프릴·리본·레이스, 큰 로고, 펑퍼짐한 롱스커트, 아줌마 같은 조합은 금지. 부츠는 앞코가 둥글거나 각진 시크한 디자인만 쓰고, 앞코가 뾰족한 부츠는 금지.';

// ===== 여주 드레스 (파티·행사·결혼식 등 격식 있는 장면에서만) =====
