const VITA_RULE='. 비타는 금발에 늑대 귀와 꼬리가 있는 늑대 수인. 동화 속 숲 마을 청년 같은 귀엽고 활기찬 차림. 성인 남성 체형으로 그리고 어린아이처럼 작고 앳되게 그리지 않는다. 늑대 귀와 꼬리는 옷 밖으로 자연스럽게 나온다. 현대 사복(후드티, 청바지, 운동화, 패딩), 갑옷, 과한 판타지 장식은 금지.';
