  const parts=[suit,'검정 군화'];const e=/조종석|비행 중|이륙|착륙/.test(sc)?'비행 장갑':rnd(KAYA_PILOT.extra);if(e!=='없음')parts.push(e);
  return `군복 — ${parts.join(', ')} / 헤어 — ${rnd(KAYA_PILOT.hair)}`;
