const GUDAL_RULE='. 조직의 보스다운 고급 테일러링과 여유로운 권위. 같은 색과 소재의 수트 재킷과 팬츠를 한 벌로 맞추며 넉넉한 어깨와 자연스럽게 떨어지는 바지 실루엣, 깨끗한 원단과 절제된 디테일을 유지한다. 경호원·직장인처럼 획일적이거나 과도하게 꾸민 호스트풍 차림은 피한다. 번쩍이는 원단, 스키니 팬츠, 과하게 좁은 라펠, 과장된 금장·장식, 과도하게 타이트하거나 헐렁한 핏은 금지. 기존 이레즈미 문신은 옷 밖으로 노출되는 부위에만 정확하게 표현한다.';
function makeGudalSuit(){
 const r=Math.random(),name=r<.70?'classic':r<.92?'dark':'stripe',st=GUDAL_STYLES[name],color=rnd(st.color),fabric=name==='stripe'?'은은한 가는 핀스트라이프 울':'고급 무광 울';
 return rnd(st.brand)+' 스타일 보스 수트 — '+[color+' '+fabric+' '+rnd(st.cut)+'와 같은 색·소재의 테일러드 팬츠',rnd(st.shirt),rnd(st.shoes)].join(', ');
}
const LAST_GUDAL_KEY='chat2img_codex_last_gudal';
function pickGudalSuit(){
  let last='';try{last=localStorage.getItem(LAST_GUDAL_KEY)||'';}catch(e){}
  let pick=makeGudalSuit();let g=0;while(pick===last&&g++<5)pick=makeGudalSuit();
  try{localStorage.setItem(LAST_GUDAL_KEY,pick);}catch(e){}
  return pick;
}

