  color:['네이비','스카이블루','올리브','크림','베이지','버건디','블랙','민트'],
  item:['무지 보드쇼츠','스트라이프 보드쇼츠','하와이안 패턴 보드쇼츠','짧은 스윔 쇼츠','무릎 길이 스윔 쇼츠'],
