  bottom:['와이드 슬랙스','와이드 치노 팬츠','진청 와이드 데님','깨끗한 원톤 중청 와이드 데님','카고 팬츠','울 와이드 팬츠'],
  outer:['오버핏 레더 재킷','두꺼운 울 오버코트','무톤 재킷','오버핏 워크 재킷','오버핏 블레이저(캐주얼 단독)','오버핏 니트 카디건','없음','없음','없음'],
