const IRIM_RULE='. 권이림은 28살 직장인, 188cm에 넓은 어깨와 탄탄한 체격. 무심하게 툭 걸쳐도 멋 부린 티가 나는 스트릿·아메카지 룩. 가죽 재킷·봄버·필드 재킷 같은 멋있는 겉옷 위주로, 백수처럼 보이는 후줄근한 차림(플리스, 늘어난 후드티, 트레이닝 상하의 세트, 등산복 차림)은 밖에서는 금지. 적힌 브랜드 옷 그대로 그린다. 팔라스 로고처럼 큰 로고가 박힌 로고 플레이 옷은 금지. 봄버 재킷은 허용. 볼캡·버킷햇·반바지·연청 데님은 금지.';
function makeIrimOutfit(scene){
  const sc=scene||'';
  if(/결혼식|장례식|상견례|제사|명절|본식|피로연/.test(sc))return `격식 차림 — 블랙 울 수트, 흰 셔츠, 블랙 솔리드 넥타이, 블랙 더비 구두`;
  if(/집에서|집 안|집안|거실|침실|침대|소파|부엌|자취방|원룸/.test(sc)&&!/출근|회사|외출|나가|약속|데이트/.test(sc))
    return `집 편한 차림 — ${rnd(IRIM_HOME.top)}, ${rnd(IRIM_HOME.bottom)}`;
  const work=/회사|사무실|출근|회의|미팅|업무|야근|퇴근|출장/.test(sc);
  const winter=/겨울|눈 오|눈이|추워|추운|영하|패딩|크리스마스|연말|입김/.test(sc),summer=!winter&&/여름|더운|더워|폭염|바다|해변|반팔|장마/.test(sc);
  const weather=/비 오|비가|빗속|장마|폭설|눈보라|등산|산에|캠핑|트레킹/.test(sc);
  let top=rnd(IRIM.top),bottom=rnd(IRIM.bottom),outer=rnd(IRIM.outer);
  if(work){bottom=rnd(['블랙 와이드 슬랙스','캐피탈 블랙 와이드 팬츠','리얼맥코이 진청 로우 데님']);top=rnd(['블랙 크루넥 니트','캐피탈 스마일 키타 니트(네이비)','더블탭스 올리브 정글 셔츠(단추 풀고 블랙 티셔츠 위에 걸침)','리얼맥코이 블랙 헨리넥 티셔츠']);if(/트랙 재킷/.test(outer))outer='리얼맥코이 부코 블랙 가죽 라이더 재킷';}
  if(summer){top=rnd(['히스테릭 글래머 블랙 그래픽 티셔츠','히스테릭 글래머 화이트 그래픽 티셔츠','리얼맥코이 블랙 포켓 티셔츠','더블탭스 올리브 정글 셔츠(단추 풀고 블랙 티셔츠 위에 걸침)']);outer='없음';}
  else if(weather)outer=rnd(IRIM_WEATHER);
  else if(winter&&(outer==='없음'||/트랙 재킷|덱 재킷|M-65/.test(outer)))outer=rnd(['리얼맥코이 A-2 브라운 가죽 플라이트 재킷','리얼맥코이 MA-1 블랙 봄버 재킷','캐피탈 링 코트(네이비)','블랙 울 오버코트','리얼맥코이 부코 블랙 가죽 라이더 재킷']);
  if(/카디건/.test(top)&&outer!=='없음'&&!/코트/.test(outer))outer='없음';
  const parts=[top,bottom];if(outer!=='없음')parts.push(outer);parts.push(rnd(IRIM.shoes));
  const acc=rnd(IRIM.acc);if(acc!=='없음')parts.push(acc);
  return `멋 부린 스트릿·아메카지 — ${parts.join(', ')}`;
}
const LAST_IRIM_KEY='chat2img_codex_last_irim';
function pickIrimOutfit(scene){
  let last='';try{last=localStorage.getItem(LAST_IRIM_KEY)||'';}catch(e){}
  let pick=makeIrimOutfit(scene);let g=0;while(pick===last&&g++<5)pick=makeIrimOutfit(scene);
  try{localStorage.setItem(LAST_IRIM_KEY,pick);}catch(e){}
  return pick;
}
