      let url;try{url=new URL(raw,location.href).href;}catch(_){throw new Error('올바른 이미지 URL을 입력하세요.');}
      if(!/^https?:\/\//i.test(url)&&!/^data:image\//i.test(url))throw new Error('HTTP(S) 이미지 URL만 사용할 수 있습니다.');
